const std::vector<uint8_t>*
WarframeExporter::Audio::findVorbisSetupHeader(int channels, int sampleRate)
{
	if (channels == 1 && sampleRate == 44100)
		return &g_setup1ch44100;
	if (channels == 2 && sampleRate == 44100)
		return &g_setup2ch44100;
	if (channels == 1 && sampleRate == 32000)
		return &g_setup1ch32000;
	if (channels == 2 && sampleRate == 32000)
		return &g_setup2ch32000;
	return nullptr;
}